# Generates ffmpeg-playground/src/vp9.rs.
import re, sys
ex = {l.split("\t")[1].strip(): l.split("\t")[0].split("aarch64_")[1] + ".S" for l in open(sys.argv[1]) if "vp9" in l.split("\t")[0]}
out = ['''//! libavcodec/aarch64 vp9mc*, vp9itxfm*, vp9lpf* (8, 10 and 12 bit).
//! Generated by gen/vp9.py. High bit depths use u16 pixels with byte strides.
//!
//! MC: an sz-wide block of h rows; the 8-tap filters read 3 samples before
//! and 4 after in the direction they filter. VP9 blocks are sz x {sz/2, sz,
//! 2sz}, and the 2-D wrapper runs the horizontal pass over h + 8 rows (into a
//! temp of ((1 + (sz < 64)) * sz + 8) rows), so h is at most 2 * sz + 8 (72
//! for 64). Prediction block heights are 4..64 in steps of 4 (vp9_mc_template.c:
//! sub-8x8 chroma is still 4 rows), so h -- and h + 8 -- is a multiple of 4,
//! which the copy/avg and vertical loops (4 rows an iteration) rely on.
//! mx/my index the 16-entry filter banks.
//! The horizontal filters' source runs one pixel past the 8-tap footprint:
//! vp9recon.c reads in place only where that pixel exists ("The arm/aarch64
//! _h filters read one more pixel than what actually is needed, so switch to
//! emulated edge if that would read beyond the bottom right block").
//! Loop filters: filter widths 4 and 8 touch 4 samples each side of the edge,
//! 16 touches 8; "44/48/84/88" are two 8-sample segments with those widths.
//! h filters a vertical edge (samples left and right), v a horizontal one.
use bums_macros as bums;
''']
def emit(name, args, pre, sig):
    out.append(f'''#[bums::check_mem_safe("{ex[name]}", {", ".join(args)},
    [{", ".join(pre)}])]
fn {name}({sig});
''')
for name in sorted(ex):
    m = re.match(r"ff_vp9_(copy|avg)(\d+)(_16)?_(neon|aarch64)$", name)
    if m:
        op, n, hb = m.group(1), int(m.group(2)), bool(m.group(3))
        ty, el = ("u16", 2) if hb else ("u8", 1)
        hmax = 2 * (n // el if op == "copy" else n) + 8 if False else 128
        row = lambda s: s if el == 1 else f"{s} / 2"
        emit(name, ["dst.as_mut_ptr()", "dst_stride", "src.as_ptr()", "src_stride", "h", "mx", "my"],
             [f"dst.len() == (h - 1) * {row('dst_stride')} + {n}", f"src.len() == (h - 1) * {row('src_stride')} + {n}",
              f"dst_stride >= {n * el}", f"src_stride >= {n * el}", "dst_stride <= 1073741824", "src_stride <= 1073741824",
              "h % 4 == 0", "h >= 4", "h <= 128"] + (["dst_stride % 2 == 0", "src_stride % 2 == 0"] if el == 2 else []),
             f"dst: &mut [{ty}], dst_stride: usize, src: &[{ty}], src_stride: usize, h: usize, mx: usize, my: usize")
        continue
    m = re.match(r"ff_vp9_(put|avg)_(regular|sharp|smooth)(\d+)_(h|v)(?:_(\d+))?_neon$", name)
    if m:
        op, flt, sz, d, bd = m.group(1), m.group(2), int(m.group(3)), m.group(4), m.group(5)
        ty, el = ("u16", 2) if bd else ("u8", 1)
        row = lambda s: s if el == 1 else f"{s} / 2"
        bh, ah = (3, 4) if d == "h" else (0, 0)
        bv, av = (3, 4) if d == "v" else (0, 0)
        hmax = 2 * sz + 8 if sz < 64 else 72
        src = f"src.as_ptr().add({bv} * {row('src_stride')} + {bh})"
        emit(name, ["dst.as_mut_ptr()", "dst_stride", src, "src_stride", "h", "mx", "my"],
             [f"dst.len() == (h - 1) * {row('dst_stride')} + {sz}",
              f"src.len() == (h - 1 + {bv + av}) * {row('src_stride')} + {sz + bh + ah + (1 if d == 'h' else 0)}",
              f"dst_stride >= {sz * el}", f"src_stride >= {(sz + bh + ah) * el}", "dst_stride <= 1073741824", "src_stride <= 1073741824",
              "h % 4 == 0", "h >= 4", f"h <= {hmax}", "mx <= 15", "my <= 15"] + (["dst_stride % 2 == 0", "src_stride % 2 == 0"] if el == 2 else []),
             f"dst: &mut [{ty}], dst_stride: usize, src: &[{ty}], src_stride: usize, h: usize, mx: usize, my: usize")
        continue
    m = re.match(r"ff_vp9_(\w+?)_(\w+?)_(\d+)x\d+_add(?:_(\d+))?_neon$", name)
    if m:
        sz, bd = int(m.group(3)), m.group(4)
        ty, el = ("u16", 2) if bd else ("u8", 1)
        coef = "i32" if bd else "i16"
        row = "stride" if el == 1 else "stride / 2"
        emit(name, ["dst.as_mut_ptr()", "stride", "block.as_mut_ptr()", "eob"],
             [f"dst.len() == {sz - 1} * {row} + {sz}", f"stride >= {sz * el}", "stride <= 1073741824", f"block.len() == {sz * sz}",
              "eob >= 1", f"eob <= {sz * sz}"] + (["stride % 2 == 0"] if el == 2 else []),
             f"dst: &mut [{ty}], stride: usize, block: &mut [{coef}], eob: usize")
        continue
    m = re.match(r"ff_vp9_loop_filter_(h|v)_(\d+)_(\d+)(?:_(\d+))?_neon$", name)
    if m:
        d, wd, ln, bd = m.group(1), int(m.group(2)), int(m.group(3)), m.group(4)
        ty, el = ("u16", 2) if bd else ("u8", 1)
        row = "stride" if el == 1 else "stride / 2"
        reach = 8 if wd == 16 else 4
        if d == "v":
            ptr = f"dst.as_mut_ptr().add({reach} * {row})"
            length = f"dst.len() == {2 * reach - 1} * {row} + {ln}"
            smin = ln * el
        else:
            ptr = f"dst.as_mut_ptr().add({reach})"
            length = f"dst.len() == {ln - 1} * {row} + {2 * reach}"
            smin = 2 * reach * el
        emit(name, [ptr, "stride", "e", "i", "h"],
             [length, f"stride >= {smin}", "stride <= 1073741824"] + (["stride % 2 == 0"] if el == 2 else []),
             f"dst: &mut [{ty}], stride: usize, e: u32, i: u32, h: u32")
        continue
    print("skip", name, file=sys.stderr)
print("\n".join(out))
